#!/usr/bin/env node

const https = require('https');
const fs = require('fs');
const path = require('path');

const API_URL = 'node.meerfans.club';
const API_PATH = '/api/status';
const LOG_FILE = path.join(__dirname, '../logs/node-monitor.log');

const log = (msg) => {
  const timestamp = new Date().toISOString();
  const logMsg = `[${timestamp}] ${msg}\n`;
  fs.appendFileSync(LOG_FILE, logMsg);
  console.log(msg);
};

const checkNodes = () => {
  return new Promise((resolve, reject) => {
    const options = {
      hostname: API_URL,
      path: API_PATH,
      method: 'GET',
      timeout: 10000
    };

    const req = https.request(options, (res) => {
      let data = '';
      res.on('data', chunk => data += chunk);
      res.on('end', () => {
        try {
          resolve(JSON.parse(data));
        } catch (e) {
          reject(new Error('JSON解析失败'));
        }
      });
    });

    req.on('error', reject);
    req.on('timeout', () => {
      req.destroy();
      reject(new Error('请求超时'));
    });

    req.end();
  });
};

const analyzeNodes = (data) => {
  const alerts = [];
  const nodes = data.nodes || {};

  // 获取最高高度
  let maxHeight = 0;
  for (const [name, node] of Object.entries(nodes)) {
    const height = node?.stateroot?.Height || 0;
    if (height > maxHeight) maxHeight = height;
  }

  // 检查每个节点
  for (const [name, node] of Object.entries(nodes)) {
    const stateroot = node?.stateroot || {};
    const height = stateroot.Height || 0;
    const valid = stateroot.Valid;

    // 检查 Valid 状态
    if (valid === false) {
      alerts.push(`🚨 节点异常: ${name} (Valid=false)`);
    }

    // 检查高度落后（超过10个块）
    if (maxHeight - height > 10) {
      alerts.push(`⚠️ 节点高度落后: ${name} (Height=${height}, 最高=${maxHeight})`);
    }
  }

  return { alerts, nodes, maxHeight };
};

const main = async () => {
  try {
    log('开始检查节点状态...');
    const data = await checkNodes();
    const { alerts, nodes, maxHeight } = analyzeNodes(data);

    if (alerts.length > 0) {
      // 有异常，输出告警信息
      for (const alert of alerts) {
        log(alert);
      }
      // 发送通知（这里先输出，你可以配置通知方式）
      console.log('\n=== 节点告警 ===');
      for (const alert of alerts) {
        console.log(alert);
      }
    } else {
      log('所有节点正常');
    }

    // 输出状态摘要
    console.log('\n📊 节点状态摘要:');
    for (const [name, node] of Object.entries(nodes)) {
      const height = node?.stateroot?.Height || 0;
      const valid = node?.stateroot?.Valid ? '✅' : '❌';
      console.log(`  ${valid} ${name.replace(/^.-/, '')}: Height=${height}`);
    }

  } catch (err) {
    log(`ERROR: ${err.message}`);
    console.log('⚠️ 节点监控异常:', err.message);
    process.exit(1);
  }
};

main();

